CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY,name text NOT NULL,logo_url text);
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),email text NOT NULL UNIQUE,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('admin','operator','viewer')),active boolean NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS sites(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,address text NOT NULL,is_arquindex boolean NOT NULL DEFAULT FALSE,UNIQUE(id,tenant_id));
CREATE TABLE IF NOT EXISTS rules(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),doc_type text NOT NULL,active_years int NOT NULL DEFAULT 0 CHECK(active_years>=0),archive_years int NOT NULL DEFAULT 0 CHECK(archive_years>=0),final_action text NOT NULL DEFAULT 'review',reference text,UNIQUE(tenant_id,doc_type));
CREATE TABLE IF NOT EXISTS boxes(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),code text NOT NULL,department text NOT NULL,doc_type text NOT NULL,description text,site_id uuid NOT NULL,shelf text,close_date date,state text NOT NULL DEFAULT 'stored',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,code),FOREIGN KEY(site_id,tenant_id) REFERENCES sites(id,tenant_id));
CREATE TABLE IF NOT EXISTS requests(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),box_id uuid NOT NULL,type text NOT NULL CHECK(type IN ('move','external_storage','physical_return','digital_copy','disposal')),destination_site_id uuid,requested_date date,reason text,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),approved_by uuid,FOREIGN KEY(box_id,tenant_id) REFERENCES boxes(id,tenant_id),FOREIGN KEY(destination_site_id,tenant_id) REFERENCES sites(id,tenant_id));
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),box_id uuid NOT NULL,action text NOT NULL,from_site_id uuid,to_site_id uuid,actor_id uuid,occurred_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(box_id,tenant_id) REFERENCES boxes(id,tenant_id),FOREIGN KEY(from_site_id,tenant_id) REFERENCES sites(id,tenant_id),FOREIGN KEY(to_site_id,tenant_id) REFERENCES sites(id,tenant_id));
